WITH base AS (SELECT *, CASE WHEN quantity >= 7 THEN 'High' WHEN quantity >= 2 THEN 'Medium' ELSE 'Low' END AS quantity_level FROM order_items WHERE quantity IS NULL) SELECT *, LAG(quantity, 2) OVER (PARTITION BY product_id, order_id ORDER BY quantity, id) AS prev_quantity, LAG(unit_price, 2) OVER (PARTITION BY order_id, product_id ORDER BY quantity, id) AS prev_unit_price, DENSE_RANK() OVER (PARTITION BY order_id ORDER BY quantity DESC NULLS LAST) AS quantity_dense_rank FROM base
